package com.bank.product.controller;
import com.bank.product.dto.*; import com.bank.product.dto.ProductDtos.*; import com.bank.product.model.ProductStatus; import com.bank.product.service.ProductService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/legacy/api/product") @RequiredArgsConstructor public class ProductController {private final ProductService service;
 @PostMapping @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<ProductResponse>> create(@Valid @RequestBody ProductRequest r,Authentication a){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(service.create(r,a.getName()),"Product created"));}
 @PutMapping("/{code}") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<ProductResponse> update(@PathVariable String code,@Valid @RequestBody ProductRequest r,Authentication a){return ApiResponse.success(service.update(code,r,a.getName()),"Product updated");}
 @PatchMapping("/{code}/status") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<ProductResponse> status(@PathVariable String code,@RequestParam ProductStatus status,@RequestParam(required=false) String approvalStatus,Authentication a){return ApiResponse.success(service.status(code,status,approvalStatus,a.getName()),"Lifecycle updated");}
 @GetMapping("/{code}") public ApiResponse<ProductResponse> get(@PathVariable String code){return ApiResponse.success(service.get(code),"Product retrieved");}
 @GetMapping("/search") public ApiResponse<List<ProductSummary>> search(@RequestParam(required=false) String productType,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate startDate,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate endDate){return ApiResponse.success(service.search(productType,startDate,endDate),"Products retrieved");}
 @GetMapping("/{code}/pricing") public ApiResponse<PricingResponse> pricing(@PathVariable String code,@RequestParam String categoryCode,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate asOf){return ApiResponse.success(service.pricing(code,categoryCode,asOf),"Pricing resolved");}
 @DeleteMapping("/{code}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> delete(@PathVariable String code){service.delete(code);return ResponseEntity.noContent().build();}
}
